insert into public.sites (slug, body_id, analog_of, name, region, terrain_type, description, soil, lat, lng, palette, status, source) values
  ('atacama', 'earth', 'mars', 'Desierto de Atacama', 'Chile', 'Desierto hiperárido', 'El lugar no polar más seco de la Tierra. Sus suelos con percloratos y su baja actividad microbiana lo hacen un banco de pruebas para rovers y búsqueda de vida en Marte.', 'Sales, percloratos y yeso', -24.5, -69.25, array['#7c2d12', '#c2410c', '#fdba74'], 'published', 'curated'),
  ('lanzarote', 'earth', 'moon', 'Tubos de lava de Lanzarote', 'Islas Canarias, España', 'Tubos de lava basálticos', 'Cavidades volcánicas análogas a los tubos de lava lunares, candidatos a refugio contra la radiación para futuras bases.', 'Basalto y escoria volcánica', 29.05, -13.43, array['#1c1917', '#44403c', '#f59e0b'], 'published', 'curated'),
  ('mcmurdo', 'earth', 'mars', 'Valles Secos de McMurdo', 'Antártida', 'Desierto polar frío', 'Valles libres de hielo con permafrost y vientos katabáticos; el análogo más cercano al clima frío y seco de Marte.', 'Permafrost y arena criogénica', -77.5, 162.5, array['#0c4a6e', '#38bdf8', '#e0f2fe'], 'published', 'curated'),
  ('lonar', 'earth', 'moon', 'Cráter Lonar', 'Maharashtra, India', 'Cráter de impacto en basalto', 'Uno de los pocos cráteres de impacto sobre roca basáltica, similar a los mares lunares. Útil para estudiar vidrio de impacto y regolito.', 'Basalto Decán y maskelinita', 19.98, 76.51, array['#052e16', '#15803d', '#a3e635'], 'published', 'curated'),
  ('mojave', 'earth', 'mars', 'Desierto de Mojave', 'California, EE. UU.', 'Desierto con campos de lava', 'Sede de las antenas de espacio profundo de Goldstone y de numerosas pruebas de rovers de la NASA.', 'Arenas aluviales y basalto', 35, -116.5, array['#78350f', '#d97706', '#fde68a'], 'published', 'curated'),
  ('moon-apollo17', 'moon', null, 'Taurus-Littrow (Apolo 17)', null, null, 'Valle basáltico flanqueado por macizos; el último sitio lunar visitado por humanos.', null, 20.19, 30.77, null::text[], 'published', 'curated'),
  ('moon-apollo11', 'moon', null, 'Mare Tranquillitatis (Apolo 11)', null, null, 'Llanura de basalto antigua y suave: el aterrizaje más seguro.', null, 0.67, 23.47, null::text[], 'published', 'curated'),
  ('moon-shackleton', 'moon', null, 'Cráter Shackleton (polo sur)', null, null, 'Fondo en sombra perpetua con posible hielo de agua; objetivo clave de Artemis.', null, -89.9, 129.8, null::text[], 'published', 'curated'),
  ('moon-tycho', 'moon', null, 'Cráter Tycho', null, null, 'Cráter joven con terreno muy rugoso y rocas expuestas.', null, -43.3, -11.36, null::text[], 'published', 'curated'),
  ('moon-marius', 'moon', null, 'Colinas de Marius (tubos de lava)', null, null, 'Campo volcánico con tragaluces hacia tubos de lava, refugios naturales contra la radiación.', null, 14.1, -56.8, null::text[], 'published', 'curated'),
  ('moon-aristarchus', 'moon', null, 'Meseta de Aristarco', null, null, 'Meseta volcánica con depósitos piroclásticos, fuente potencial de recursos.', null, 23.7, -47.4, null::text[], 'published', 'curated'),
  ('mars-jezero', 'mars', null, 'Cráter Jezero', null, null, 'Antiguo lago con delta fluvial; sitio del rover Perseverance.', null, 18.38, 77.58, null::text[], 'published', 'curated'),
  ('mars-gale', 'mars', null, 'Cráter Gale', null, null, 'Montaña sedimentaria central explorada por Curiosity.', null, -5.4, 137.8, null::text[], 'published', 'curated'),
  ('mars-olympus', 'mars', null, 'Olympus Mons', null, null, 'El volcán más grande del sistema solar, de basalto y lava endurecida.', null, 18.65, -133.8, null::text[], 'published', 'curated'),
  ('mars-valles', 'mars', null, 'Valles Marineris', null, null, 'Sistema de cañones de más de 4 000 km con paredes de capas expuestas.', null, -14, -59, null::text[], 'published', 'curated'),
